document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("renovation-cost-form"),t=document.getElementById("renovation-cost-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("renovation-area").value),o=document.getElementById("renovation-type").value;if(n<=0)return t.textContent="Please enter a positive area value.",void 0;if(!o)return t.textContent="Please select a renovation type.",void 0;let a,i,s;if("custom"===o){const e=parseFloat(document.getElementById("renovation-price").value);if(e<=0)return t.textContent="Please enter a cost per square foot.",void 0;a=i=e,s="Custom renovation"}else switch(o){case"basic":a=15,i=30,s="Basic/Cosmetic renovation";break;case"mid":a=30,i=60,s="Mid-range renovation";break;case"high":a=60,i=120,s="High-end renovation";break;case"luxury":a=120,i=200,s="Luxury renovation";break;case"kitchen":a=75,i=200,s="Kitchen renovation";break;case"bathroom":a=100,i=250,s="Bathroom renovation"}const r=n*a,c=n*i,l=(r+c)/2,d=.2*l,p=l+d;t.innerHTML=a===i?`\n          <div class="result-section">\n            <h4>Renovation Cost Estimate:</h4>\n            <p><strong>$${r.toLocaleString()}</strong></p>\n            <p>${n} sq ft × $${a}/sq ft</p>\n          </div>\n          <div class="result-breakdown">\n            <h4>Budget Planning:</h4>\n            <p>Base cost: $${r.toLocaleString()}</p>\n            <p>20% contingency: $${d.toLocaleString()}</p>\n            <p><strong>Total budget needed: $${p.toLocaleString()}</strong></p>\n          </div>\n          <div class="result-tips">\n            <p><em>💡 Always add 20% contingency for unexpected costs</em></p>\n            <p><em>📋 Get detailed quotes from multiple contractors</em></p>\n          </div>\n        `:`\n          <div class="result-section">\n            <h4>${s} Cost Estimate:</h4>\n            <p><strong>$${r.toLocaleString()} - $${c.toLocaleString()}</strong></p>\n            <p>${n} sq ft × $${a}-${i}/sq ft</p>\n            <p>Average estimate: $${l.toLocaleString()}</p>\n          </div>\n          <div class="result-breakdown">\n            <h4>Budget Planning (Average):</h4>\n            <p>Base cost: $${l.toLocaleString()}</p>\n            <p>20% contingency: $${d.toLocaleString()}</p>\n            <p><strong>Total budget needed: $${p.toLocaleString()}</strong></p>\n          </div>\n          <div class="result-tips">\n            <p><em>💰 Costs vary significantly by location and material choices</em></p>\n            <p><em>🔍 Get detailed contractor quotes for accurate pricing</em></p>\n            <p><em>📅 Consider seasonal pricing and contractor availability</em></p>\n          </div>\n        `})});